insert into public.library_roles (id, label, short_label, lead, intro, sort_order) values
  ('des', 'Designers', 'Design', 'Designers:', 'start with WCAG 2.2''s design-related criteria, the Mercury design system and W3C''s designing tips. Annotate focus order, accessible names and headings in every handoff, in English and French.', 1),
  ('pm', 'Product managers', 'PM', 'Product managers:', 'start with the ACA regulations'' December 2027 and 2028 deadlines and W3C''s roles mapping (ARRM) to assign ownership. Budget for testing with people with disabilities and for conformity assessments.', 2),
  ('po', 'Product owners', 'PO', 'Product owners:', 'write WCAG and EN 301 549 references into acceptance criteria, and don''t accept a story as done until the release checklist passes.', 3),
  ('dev', 'Developers', 'Dev', 'Developers:', 'start with the ARIA Authoring Practices and the platform guides, add automated checks to CI, then test with a screen reader in both languages.', 4),
  ('qa', 'QA', 'QA', 'QA:', 'use W3C Easy Checks and WCAG-EM for method, CAN/ASC-EN 301 549 for scope, and log each issue against its WCAG criterion or EN clause.', 5),
  ('proc', 'Procurement', 'Procurement', 'Procurement:', 'from 5 December 2028 the public sector and large businesses must check purchased apps and web pages. Ask vendors for an Accessibility Conformance Report against EN 301 549 (the VPAT EU or INT edition), not WCAG alone.', 6);
insert into public.roles (id, sort_order, library_role, name_en, name_fr, blurb_en, blurb_fr, plural_en, plural_fr, deadline_2027_en, deadline_2027_fr, deadline_2028_en, deadline_2028_fr, note_en, note_fr) values
  ('dev', 1, 'dev', 'Developer', 'Développement', 'Web, iOS and Android code', 'Code Web, iOS et Android', 'developers', 'le développement', 'New and updated web pages, if we are on the federal public-sector timeline', 'Pages Web nouvelles et mises à jour, si nous suivons l''échéancier du secteur public fédéral', 'New mobile apps conform; existing public-facing apps are assessed', 'Les nouvelles applications mobiles sont conformes; les applications publiques existantes sont évaluées', 'CAN/ASC-EN 301 549:2024 requires WCAG 2.1 AA today. We build to WCAG 2.2 AA, which adds 6 criteria.', 'La CAN/ASC-EN 301 549:2024 exige les WCAG 2.1 AA aujourd''hui. Nous visons les WCAG 2.2 AA, qui ajoutent 6 critères.'),
  ('po', 2, 'po', 'Product owner', 'Propriétaire de produit', 'Stories, acceptance criteria, releases', 'Récits, critères d''acceptation, versions', 'product owners', 'les propriétaires de produit', 'New and updated web pages conform, and a website accessibility statement is published, if we are on the federal public-sector timeline', 'Les pages Web nouvelles et mises à jour sont conformes et un énoncé d''accessibilité du site est publié, si nous suivons l''échéancier du secteur public fédéral', 'Mobile apps, digital documents and purchased products conform; the statement covers apps and documents', 'Les applications mobiles, les documents numériques et les produits achetés sont conformes; l''énoncé couvre les applications et les documents', 'Canada Post Accessibility Plan 2026–2028: 67% of digital products are usability-tested with people with disabilities today; the target is 97% by 2028.', 'Plan sur l''accessibilité 2026-2028 de Postes Canada : 67 % des produits numériques sont testés auprès de personnes en situation de handicap aujourd''hui; la cible est de 97 % d''ici 2028.'),
  ('des', 3, 'des', 'Product designer', 'Design de produits', 'Flows, components, handoff', 'Parcours, composants, transfert', 'product designers', 'le design de produits', 'New and updated web pages conform, if we are on the federal public-sector timeline. Designs for 2027 web releases need to meet it now.', 'Les pages Web nouvelles et mises à jour sont conformes, si nous suivons l''échéancier du secteur public fédéral. Les maquettes des versions Web de 2027 doivent déjà y répondre.', 'New mobile apps conform; existing public-facing apps are assessed', 'Les nouvelles applications mobiles sont conformes; les applications publiques existantes sont évaluées', 'WCAG 2.2 adds design decisions such as 2.5.8 Target Size and 2.4.11 Focus Not Obscured. CAN/ASC-EN 301 549:2024 requires WCAG 2.1 AA today; we build to 2.2 AA.', 'Les WCAG 2.2 ajoutent des décisions de conception, comme 2.5.8 Taille de la cible et 2.4.11 Focus non masqué. La CAN/ASC-EN 301 549:2024 exige les WCAG 2.1 AA aujourd''hui; nous visons les WCAG 2.2 AA.'),
  ('qa', 4, 'qa', 'QA analyst', 'Assurance qualité', 'Test plans across web, iOS and Android', 'Plans de test Web, iOS et Android', 'QA analysts', 'l''assurance qualité', 'New and updated web pages, if we are on the federal public-sector timeline', 'Pages Web nouvelles et mises à jour, si nous suivons l''échéancier du secteur public fédéral', 'New mobile apps conform; existing public-facing apps are assessed', 'Les nouvelles applications mobiles sont conformes; les applications publiques existantes sont évaluées', 'Test to WCAG 2.2 AA plus the EN 301 549 clauses beyond WCAG. CAN/ASC-EN 301 549:2024 requires WCAG 2.1 AA today.', 'Testez selon les WCAG 2.2 AA et les articles de l''EN 301 549 qui vont au-delà des WCAG. La CAN/ASC-EN 301 549:2024 exige les WCAG 2.1 AA aujourd''hui.'),
  ('proc', 5, 'proc', 'Procurement', 'Approvisionnement', 'Buying software and services', 'Achat de logiciels et de services', 'procurement', 'l''approvisionnement', 'Federal public sector web pages; purchased products follow in 2028', 'Pages Web du secteur public fédéral; les produits achetés suivent en 2028', 'Purchased apps and web pages must be checked (public sector and businesses with 500+ employees)', 'Les applications et pages Web achetées doivent être vérifiées (secteur public et entreprises de 500 employés ou plus)', 'Keep conformance reports on file: the regulations require records to be kept for four years.', 'Conservez les rapports de conformité : le règlement exige de garder les dossiers pendant quatre ans.'),
  ('lead', 6, 'pm', 'Leadership', 'Direction', 'Deadlines, risk and progress', 'Échéances, risques et progrès', 'leadership', 'la direction', 'New and updated web pages, if we are on the federal public-sector timeline', 'Pages Web nouvelles et mises à jour, si nous suivons l''échéancier du secteur public fédéral', 'Mobile apps, digital documents and purchased products', 'Applications mobiles, documents numériques et produits achetés', 'Accessibility statements must be updated every year, and records kept for four years.', 'Les énoncés d''accessibilité doivent être mis à jour chaque année et les dossiers conservés pendant quatre ans.');
insert into public.role_criteria (role_id, position, tag, title_en, title_fr, summary_en, summary_fr, detail_en, detail_fr) values
  ('dev', 1, 'req', '4.1.2 Name, Role, Value', '4.1.2 Nom, rôle et valeur', 'Custom controls expose a name, role and state to assistive technology.', 'Les commandes personnalisées exposent un nom, un rôle et un état aux technologies d''assistance.', 'Use native elements first. On iOS set accessibilityLabel and traits; in Compose use Modifier.semantics.', 'Utilisez d''abord les éléments natifs. Sur iOS, définissez accessibilityLabel et les traits; avec Compose, utilisez Modifier.semantics.'),
  ('dev', 2, 'req', '2.1.1 Keyboard', '2.1.1 Clavier', 'Every task works without a mouse or touch.', 'Chaque tâche fonctionne sans souris ni écran tactile.', 'Includes switch access and external keyboards on iPad and Android.', 'Y compris l''accès par contacteur et les claviers externes sur iPad et Android.'),
  ('dev', 3, 'req', '1.3.1 Info and Relationships', '1.3.1 Information et relations', 'Headings, lists, tables and form labels are in the code, not just the visuals.', 'Les titres, listes, tableaux et étiquettes de formulaire sont dans le code, pas seulement à l''écran.', 'Tie every input to its label, and link error messages with aria-describedby.', 'Associez chaque champ à son étiquette et liez les messages d''erreur avec aria-describedby.'),
  ('dev', 4, 'target', '2.4.11 Focus Not Obscured (Minimum)', '2.4.11 Focus non masqué (minimum)', 'Sticky headers and banners never fully hide the focused element.', 'Les en-têtes fixes et les bannières ne masquent jamais complètement l''élément qui a le focus.', 'New in WCAG 2.2. Not yet in CAN/ASC-EN 301 549:2024, but in our build target.', 'Nouveau dans les WCAG 2.2. Pas encore dans la CAN/ASC-EN 301 549:2024, mais compris dans notre cible.'),
  ('dev', 5, 'en', 'EN 11.7 User preferences', 'EN 11.7 Préférences de l''utilisateur', 'Software follows the platform''s text size, contrast and colour settings.', 'Le logiciel respecte les réglages de taille du texte, de contraste et de couleur de la plateforme.', 'Goes beyond WCAG. Test with Dynamic Type and Android font scale at maximum.', 'Va au-delà des WCAG. Testez avec Dynamic Type et l''échelle de police Android au maximum.'),
  ('po', 1, 'req', '3.3.1 Error Identification and 3.3.2 Labels or Instructions', '3.3.1 Identification des erreurs et 3.3.2 Étiquettes ou instructions', 'Every story with a form says how errors are shown and explained.', 'Chaque récit comportant un formulaire précise comment les erreurs sont signalées et expliquées.', 'Acceptance criterion: errors are announced and say how to fix them.', 'Critère d''acceptation : les erreurs sont annoncées et expliquent comment les corriger.'),
  ('po', 2, 'en', '1.2.2 Captions (Prerecorded) and EN 7.1', '1.2.2 Sous-titres (préenregistrés) et EN 7.1', 'Any video ships with captions, and the player lets people turn them on.', 'Toute vidéo est livrée avec des sous-titres, et le lecteur permet de les activer.', 'WCAG covers the captions; EN 301 549 clause 7.1 covers the player controls.', 'Les WCAG couvrent les sous-titres; l''article 7.1 de l''EN 301 549 couvre les commandes du lecteur.'),
  ('po', 3, 'target', '3.3.8 Accessible Authentication (Minimum)', '3.3.8 Authentification accessible (minimum)', 'Sign-in never depends on remembering or solving a puzzle. Paste and password managers work.', 'La connexion n''exige jamais de mémoriser ni de résoudre une énigme. Le collage et les gestionnaires de mots de passe fonctionnent.', 'New in WCAG 2.2. Add it to every sign-in or verification story.', 'Nouveau dans les WCAG 2.2. Ajoutez-le à chaque récit de connexion ou de vérification.'),
  ('po', 4, 'en', 'EN 12.1–12.2 Documentation and support', 'EN 12.1–12.2 Documentation et services de soutien', 'Help pages and support channels for the feature are accessible too.', 'Les pages d''aide et les canaux de soutien de la fonctionnalité sont aussi accessibles.', 'Goes beyond WCAG. Include help content and support flows in the story scope.', 'Va au-delà des WCAG. Incluez le contenu d''aide et les parcours de soutien dans la portée du récit.'),
  ('des', 1, 'req', '1.4.3 Contrast (Minimum)', '1.4.3 Contraste (minimum)', 'Text is at least 4.5:1 against its background; large text at least 3:1.', 'Le texte a un contraste d''au moins 4,5:1 avec l''arrière-plan; le grand texte, d''au moins 3:1.', 'Check every state: hover, focus and error, and both themes if you design a dark mode.', 'Vérifiez chaque état : survol, focus et erreur, et les deux thèmes si vous concevez un mode sombre.'),
  ('des', 2, 'req', '1.4.11 Non-text Contrast', '1.4.11 Contraste du contenu non textuel', 'Icons, input borders and focus indicators are at least 3:1.', 'Les icônes, les bordures de champ et les indicateurs de focus ont un contraste d''au moins 3:1.', 'A light grey input border on white often fails. Mercury''s #666666 border passes at 5.7:1.', 'Une bordure de champ gris pâle sur fond blanc échoue souvent. La bordure #666666 de Mercury réussit, à 5,7:1.'),
  ('des', 3, 'req', '2.4.7 Focus Visible', '2.4.7 Visibilité du focus', 'Every interactive element has a visible focus state in the design file.', 'Chaque élément interactif a un état de focus visible dans le fichier de conception.', 'Design it once per component, not per screen, so engineering can reuse it.', 'Concevez-le une fois par composant, et non par écran, pour que l''ingénierie puisse le réutiliser.'),
  ('des', 4, 'target', '2.5.8 Target Size (Minimum)', '2.5.8 Taille de la cible (minimum)', 'Targets are at least 24 × 24 px; design to 44 pt on iOS and 48 dp on Android.', 'Les cibles mesurent au moins 24 × 24 px; visez 44 pt sur iOS et 48 dp sur Android.', 'New in WCAG 2.2. Not yet in CAN/ASC-EN 301 549:2024, but in our build target.', 'Nouveau dans les WCAG 2.2. Pas encore dans la CAN/ASC-EN 301 549:2024, mais compris dans notre cible.'),
  ('des', 5, 'req', '1.3.1 Info and Relationships', '1.3.1 Information et relations', 'Headings, reading order and labels are annotated so engineering builds the structure you designed.', 'Les titres, l''ordre de lecture et les étiquettes sont annotés pour que l''ingénierie construise la structure prévue.', 'This is what the "Do this now" action covers.', 'C''est l''objet de l''action « À faire maintenant ».'),
  ('qa', 1, null, 'WCAG-EM evaluation method', 'Méthode d''évaluation WCAG-EM', 'One method to scope, sample and report across web, iOS and Android.', 'Une seule méthode pour délimiter, échantillonner et rendre compte, sur le Web, iOS et Android.', 'W3C''s WCAG-EM: define the scope, explore, pick a representative sample, audit, report.', 'WCAG-EM du W3C : définir la portée, explorer, choisir un échantillon représentatif, auditer, rendre compte.'),
  ('qa', 2, null, 'A screen reader per platform', 'Un lecteur d''écran par plateforme', 'NVDA or JAWS with Chrome or Firefox on Windows, VoiceOver on Mac and iOS, TalkBack on Android.', 'NVDA ou JAWS avec Chrome ou Firefox sous Windows, VoiceOver sur Mac et iOS, TalkBack sur Android.', 'Test in English and French, with the screen reader''s language set to match the page.', 'Testez en français et en anglais, avec la langue du lecteur d''écran réglée selon la page.'),
  ('qa', 3, 'en', 'EN 301 549 clauses 7, 11 and 12', 'Articles 7, 11 et 12 de l''EN 301 549', 'Video player controls, software that honours user settings, and accessible help and support.', 'Commandes du lecteur vidéo, logiciels qui respectent les réglages de l''utilisateur, aide et soutien accessibles.', 'These go beyond WCAG and are part of the Canadian standard the regulations require.', 'Ces exigences vont au-delà des WCAG et font partie de la norme canadienne exigée par le règlement.'),
  ('qa', 4, 'target', '2.4.11 Focus Not Obscured (Minimum)', '2.4.11 Focus non masqué (minimum)', 'Sticky headers, banners and chat widgets never fully hide the focused element.', 'Les en-têtes fixes, les bannières et les fenêtres de clavardage ne masquent jamais complètement l''élément qui a le focus.', 'New in WCAG 2.2, in our build target.', 'Nouveau dans les WCAG 2.2, compris dans notre cible.'),
  ('proc', 1, null, 'Purchased products are in scope from 5 Dec 2028', 'Les produits achetés sont visés à compter du 5 déc. 2028', 'The public sector and large businesses must check the apps and web pages they buy.', 'Le secteur public et les grandes entreprises doivent vérifier les applications et les pages Web qu''ils achètent.', 'From the Accessible Canada Regulations, amended December 2025.', 'Selon le Règlement canadien sur l''accessibilité, modifié en décembre 2025.'),
  ('proc', 2, 'en', 'Ask for a report against EN 301 549', 'Demandez un rapport selon l''EN 301 549', 'Request an Accessibility Conformance Report against EN 301 549, not WCAG alone.', 'Exigez un rapport de conformité en accessibilité selon l''EN 301 549, pas seulement selon les WCAG.', 'Use the ITI VPAT EU or INT edition. A WCAG-only report leaves out clauses 6, 7, 11 and 12.', 'Utilisez le VPAT de l''ITI, édition EU ou INT. Un rapport limité aux WCAG omet les articles 6, 7, 11 et 12.'),
  ('proc', 3, null, 'Remediation in the contract', 'Des corrections inscrites au contrat', 'Write fix timelines for known issues into the contract.', 'Inscrivez au contrat les délais de correction des problèmes connus.', 'Canada Post''s plan gives internal software that doesn''t meet WCAG 2.1 AA 24 months from contract signature to be fixed.', 'Le plan de Postes Canada accorde 24 mois après la signature du contrat pour corriger un logiciel interne qui ne respecte pas les WCAG 2.1 AA.'),
  ('lead', 1, null, 'Which ACA timeline applies to us', 'Quel échéancier de la LCA s''applique à nous', 'Some Crown corporations follow the public-sector timeline (2027), a year before businesses (2028).', 'Certaines sociétés d''État suivent l''échéancier du secteur public (2027), un an avant les entreprises (2028).', 'Until it is confirmed, plan to the earlier date.', 'Tant que ce n''est pas confirmé, planifiez selon la date la plus proche.'),
  ('lead', 2, null, '67% → 97% by 2028', '67 % → 97 % d''ici 2028', 'Share of digital products usability-tested with people with disabilities, now and the target.', 'Part des produits numériques testés auprès de personnes en situation de handicap, aujourd''hui et la cible.', 'Canada Post Accessibility Plan 2026–2028.', 'Plan sur l''accessibilité 2026-2028 de Postes Canada.'),
  ('lead', 3, null, 'One action per team, each sprint', 'Une action par équipe, à chaque sprint', 'Developers, designers, product owners, QA and procurement each get one thing to do in this hub.', 'Le développement, la conception, les propriétaires de produit, l''AQ et l''approvisionnement ont chacun une chose à faire dans ce centre.', 'Ask leads which action their team has completed.', 'Demandez aux responsables quelle action leur équipe a terminée.');
insert into public.role_actions (role_id, kind, title_en, title_fr, summary_en, summary_fr, button_en, button_fr, intro_en, intro_fr, steps_en, steps_fr, copy_heading_en, copy_heading_fr, copy_button_en, copy_button_fr, copy_text_en, copy_text_fr, done_button_en, done_button_fr, done_title_en, done_title_fr, done_body_en, done_body_fr, done_next_en, done_next_fr) values
  ('dev', 'do', 'Run axe in CI on your repo', 'Exécutez axe dans l''intégration continue de votre dépôt', 'Catches common failures, like missing labels and low contrast, on every pull request.', 'Repère les erreurs courantes, comme les étiquettes manquantes et le faible contraste, à chaque demande de tirage.', 'Set it up', 'Configurer', 'Add an automated accessibility test to your web repo. For native apps, use the platform audits in step 3.', 'Ajoutez un test d''accessibilité automatisé à votre dépôt Web. Pour les applications natives, utilisez les audits de la plateforme à l''étape 3.', array['Install the axe package for your test runner.', 'Add the test below and run it locally.', 'Native apps: call performAccessibilityAudit() in XCUITest, or enable AccessibilityChecks in Espresso.', 'Add the test to your CI pipeline so it runs on every pull request.']::text[], array['Installez le module axe pour votre outil de test.', 'Ajoutez le test ci-dessous et exécutez-le localement.', 'Applications natives : appelez performAccessibilityAudit() dans XCUITest ou activez AccessibilityChecks dans Espresso.', 'Ajoutez le test à votre pipeline d''intégration continue pour qu''il s''exécute à chaque demande de tirage.']::text[], 'Playwright example', 'Exemple Playwright', 'Copy snippet', 'Copier l''extrait', 'import { test, expect } from ''@playwright/test'';
