insert into public.news_items (published_on, date_label, topic_id, tag, title, body, means_lead, means, sources_label) values
  ('2026-09-02', '2 Sep 2026', 'standards', 'Standards', 'EN 301 549 V4.1.1 published: Europe moves to WCAG 2.2 AA', 'ETSI, CEN and CENELEC published the new version of Europe''s ICT accessibility standard. Web content, documents and software clauses now reference WCAG 2.2 AA instead of 2.1, real-time communication requirements were rewritten, and new annexes map the standard to the European Accessibility Act. Deque reports it is on track to be cited in the EU Official Journal around 30 November 2026.', 'For us:', 'Canada''s adopted edition is still CAN/ASC-EN 301 549:2024, based on EN 301 549:2021 (V3.2.1) and WCAG 2.1. Accessibility Standards Canada says it follows the international review cycle but hasn''t announced a date to adopt V4.1.1. Building to WCAG 2.2 AA now avoids rework when it does.', 'Sources:'),
  ('2026-09-10', 'Sep 2026', 'standards', 'Standards', 'New WCAG 3 Working Draft opens for review', 'W3C published another WCAG 3 Working Draft in September, following the March 2026 draft. WCAG 3 is still a draft: it replaces pass/fail success criteria with more granular requirements and a Bronze/Silver/Gold conformance model. W3C says WCAG 2 will not be deprecated for several years after WCAG 3 is final.', 'For us:', 'read it, don''t build to it. No law or procurement rule, including the ACA''s, references WCAG 3.', 'Sources:'),
  ('2026-09-16', '16 Sep 2026', 'research', 'Research', 'AI speeds up building faster than it speeds up accessibility testing', 'Level Access''s eighth State of Digital Accessibility report found about 80% of accessibility professionals now use AI, but only around 30% say it has helped their QA and testing. Applause''s 2026 report found 78% of organisations use AI for accessibility work, with 90% combining it with manual testing.', 'For us:', 'AI-generated UI still needs manual keyboard and screen reader passes. Treat AI output like a new contributor''s pull request.', 'Sources:'),
  ('2026-07-08', '8 Jul 2026', 'law', 'Other law & enforcement', 'US digital accessibility lawsuits on pace for a record year', 'UsableNet''s midyear report projects about 6,176 website and app lawsuits in the US in 2026, nearly 20% above 2025. About two in three website suits target companies under $50M in revenue, and app lawsuits are a growing share.', 'For us:', 'relevant for any product sold into the US. Checkout, sign-in and account flows are the usual targets.', 'Sources:'),
  ('2026-06-28', '28 Jun 2026', 'law', 'Other law & enforcement', 'European Accessibility Act turns one; enforcement is ramping up', 'The EAA has been enforceable since 28 June 2025. National authorities are building audit capacity: Italy''s AGID introduced a two-stage model in May 2026, and the first enforcement actions were injunctions filed against retailers in France in November 2025.', 'For us:', 'applies only to products and services offered to consumers in the EU.', 'Sources:'),
  ('2026-06-16', '16 Jun 2026', 'mobile', 'Mobile platforms', 'Android 17 ships with accessibility API restrictions and large-screen changes', 'Android 17 (API level 37) blocks apps that aren''t genuine accessibility tools from using the Accessibility API under Advanced Protection Mode. Apps targeting API 37 can no longer lock orientation or disable resizing on large screens.', 'For us:', 'test layouts in landscape and on tablets and foldables at large font sizes.', 'Sources:'),
  ('2026-05-19', '19 May 2026', 'mobile', 'Mobile platforms', 'Apple previews AI-powered accessibility features for its 27 releases', 'Apple announced Apple Intelligence upgrades to VoiceOver, Magnifier, Voice Control (including natural-language commands) and Accessibility Reader, plus generated subtitles and power wheelchair control with Apple Vision Pro.', 'For us:', 'AI image descriptions don''t replace our own labels. Voice Control works best when visible labels match accessible names.', 'Sources:'),
  ('2026-05-01', 'May 2026', 'mobile', 'Mobile platforms', 'Apple pushes developers to prepare Accessibility Nutrition Labels', 'App Store product pages show which accessibility features an app supports. A feature can only be claimed if users can complete all of the app''s common tasks with it. Labels are optional today; Apple says they will become required for new apps and updates.', 'For us:', 'the same common-task audit feeds the ACA mobile app conformity assessment due in December 2028.', 'Sources:'),
  ('2026-04-20', '20 Apr 2026', 'law', 'Other law & enforcement', 'US DOJ extends ADA Title II web and app deadlines by one year', 'US state and local governments now have until 26 April 2027 (population 50,000+) or 26 April 2028 to meet WCAG 2.1 AA for web content and mobile apps.', 'For us:', 'relevant only to products sold to US public entities.', 'Sources:'),
  ('2026-02-28', 'Feb 2026', 'research', 'Research', 'WebAIM Million 2026: the web got less accessible', '95.9% of the top million home pages failed, averaging 56.1 errors per page. The most common failures were low-contrast text (83.9% of pages), missing alt text (53.1%), missing form labels (51%), empty links (46.3%) and empty buttons (30.6%). Pages with ARIA averaged 59.1 errors versus 42 without.', 'For us:', 'the top five failures are all catchable in design review and automated CI. More ARIA is not better ARIA.', 'Source:'),
  ('2025-12-05', '5 Dec 2025', 'canada', 'Canada', 'Digital accessibility rules added to the Accessible Canada Regulations', 'The federal government registered amendments to the Accessible Canada Regulations covering web pages, mobile apps, digital documents, procurement and training. They require conformance with CAN/ASC-EN 301 549, phased in from 5 December 2027 for the federal public sector and 5 December 2028 for federally regulated businesses with 100 or more employees. Organisations must also publish accessibility statements, update them annually and keep records for four years.', 'For us:', 'this is the rule that turns CAN/ASC-EN 301 549 from a voluntary standard into a requirement. See the Accessible Canada Act panel in Standards & law for the full timeline.', 'Sources:');
insert into public.news_sources (news_id, position, label, url) values
  ((select id from public.news_items where title = 'EN 301 549 V4.1.1 published: Europe moves to WCAG 2.2 AA'), 1, 'National Disability Authority', 'https://nda.ie/news/en301549-published'),
  ((select id from public.news_items where title = 'EN 301 549 V4.1.1 published: Europe moves to WCAG 2.2 AA'), 2, 'Deque', 'https://www.deque.com/blog/en-301-549-v4-1-1-is-final-what-changed-what-it-means-and-what-you-should-do/'),
  ((select id from public.news_items where title = 'EN 301 549 V4.1.1 published: Europe moves to WCAG 2.2 AA'), 3, 'Accessibility Standards Canada', 'https://accessible.canada.ca/en-301-549-accessibility-requirements-ict-products-and-services-1'),
  ((select id from public.news_items where title = 'New WCAG 3 Working Draft opens for review'), 1, 'W3C WAI announcement', 'https://lists.w3.org/Archives/Public/public-wai-announce/2026JulSep/0001.html'),
